--
-- Structure de la table `decaissement`
--

CREATE TABLE IF NOT EXISTS `decaissement` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `id_personnel` int(11) NOT NULL,
  `motif` varchar(2048) COLLATE utf8_unicode_ci NOT NULL,
  `montant` double(8,2) NOT NULL,
  `date` date NOT NULL,
  `annee_scolaire` varchar(9) COLLATE utf8_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci AUTO_INCREMENT=1 ;

