  `avertissement` int(11) NOT NULL DEFAULT '0',
  `blame` int(11) NOT NULL DEFAULT '0',
  `exclusion` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM  DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci AUTO_INCREMENT=3 ;

