--
-- Structure de la table `eleve`
--

CREATE TABLE IF NOT EXISTS `eleve` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `nom` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `prenom` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `date_naiss` date NOT NULL,
  `lieu_naiss` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `sexe` varchar(1) COLLATE utf8_unicode_ci NOT NULL,
  `nationalite` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `quartier` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `parent_ens` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `lien_tuteur` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `matricule` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `tel` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `status_matrimonial` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `region_origine` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `departement_origine` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `diplome_preinscription` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `annee_obtention` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `pays_obtention` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `dernier_etablissement` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `annee_sortie` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `diplome_obtenu` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `premiere_langue` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `deuxieme_langue` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `autre_langue` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `profession` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM  DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci AUTO_INCREMENT=213 ;

