--
-- Structure de la table `payement`
--

CREATE TABLE IF NOT EXISTS `payement` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `id_eleve` int(11) NOT NULL,
  `annee_scolaire` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `date_payement` date NOT NULL,
  `montant` double(8,2) NOT NULL,
  `motif` varchar(1000) COLLATE utf8_unicode_ci NOT NULL,
  `numero` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM  DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci AUTO_INCREMENT=217 ;

