--
-- Structure de la table `payement_salaire`
--

CREATE TABLE IF NOT EXISTS `payement_salaire` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `id_personnel` int(11) NOT NULL,
  `id_user` int(11) NOT NULL,
  `montant` double(8,2) NOT NULL,
  `date_p` date NOT NULL,
  `numero` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  `mois` int(11) NOT NULL,
  `heure_realise` int(11) NOT NULL,
  `primes` double(8,2) NOT NULL DEFAULT '0.00',
  `acomptes` double(8,2) NOT NULL DEFAULT '0.00',
  `cnss` double(8,2) NOT NULL DEFAULT '0.00',
  `cas_sociales` double(8,2) NOT NULL DEFAULT '0.00',
  `assurances` double(8,2) NOT NULL DEFAULT '0.00',
  `autre_retenues` double(8,2) NOT NULL DEFAULT '0.00',
  `taux` double(8,2) NOT NULL DEFAULT '0.00',
  `total` double(8,2) NOT NULL DEFAULT '0.00',
  `total_retenu` double(8,2) NOT NULL DEFAULT '0.00',
  `net_a_payer` double(8,2) NOT NULL DEFAULT '0.00',
  `annee_scolaire` varchar(9) COLLATE utf8_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM  DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci AUTO_INCREMENT=2 ;

--
-- Contenu de la table `payement_salaire`
--

INSERT INTO `payement_salaire` (`id`, `id_personnel`, `id_user`, `montant`, `date_p`, `numero`, `mois`, `heure_realise`, `primes`, `acomptes`, `cnss`, `cas_sociales`, `assurances`, `autre_retenues`, `taux`, `total`, `total_retenu`, `net_a_payer`, `annee_scolaire`) VALUES
